function reachableBySwapsAndRelabels(first: string, second: string): boolean {
  if (first.length !== second.length) return false;
  const a = new Array(26).fill(0), b = new Array(26).fill(0);
  for (let i = 0; i < first.length; i++) {
    a[first.charCodeAt(i) - 97]++;
    b[second.charCodeAt(i) - 97]++;
  }
  for (let c = 0; c < 26; c++) if ((a[c] > 0) !== (b[c] > 0)) return false;
  a.sort((x, y) => x - y);
  b.sort((x, y) => x - y);
  return a.every((x, i) => x === b[i]);
}

