function reachableBySwapsAndRelabels(first: string, second: string): boolean {
  if (first.length !== second.length) return false;
  const a = new Map<string, number>(), b = new Map<string, number>();
  for (const ch of first) a.set(ch, (a.get(ch) || 0) + 1);
  for (const ch of second) b.set(ch, (b.get(ch) || 0) + 1);
  if (a.size !== b.size) return false;
  for (const k of a.keys()) if (!b.has(k)) return false;
  const tally = new Map<number, number>();
  for (const v of a.values()) tally.set(v, (tally.get(v) || 0) + 1);
  for (const v of b.values()) {
    const t = tally.get(v) || 0;
    if (t === 0) return false;
    tally.set(v, t - 1);
  }
  return true;
}

